-- ============================================================
-- PASSWORD SECURITY MANAGEMENT
-- PostgreSQL 15+
--
-- Features:
--   1. Password policy management
--   2. Password hashing using pgcrypto bcrypt
--   3. Random salts generated by bcrypt
--   4. Password verification
--   5. Password history
--   6. Account lockout
--   7. Password expiration metadata
--   8. Security audit events
--   9. Role-based database permissions
--  10. Reporting and compliance queries
--
-- IMPORTANT:
-- Passwords are never stored as plaintext.
-- The database stores bcrypt password verifiers.
-- ============================================================

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE SCHEMA IF NOT EXISTS password_security;

SET search_path TO password_security, public;


-- ============================================================
-- 1. ENUM TYPES
-- ============================================================

CREATE TYPE account_status AS ENUM (
    'ACTIVE',
    'LOCKED',
    'DISABLED'
);

CREATE TYPE security_event_type AS ENUM (
    'ACCOUNT_CREATED',
    'AUTHENTICATION_SUCCESS',
    'AUTHENTICATION_FAILURE',
    'ACCOUNT_LOCKED',
    'PASSWORD_CHANGED',
    'PASSWORD_REJECTED',
    'PASSWORD_RESET'
);


-- ============================================================
-- 2. PASSWORD POLICY
-- ============================================================

CREATE TABLE password_policies (
    policy_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    policy_name VARCHAR(100) NOT NULL UNIQUE,

    minimum_length INTEGER NOT NULL DEFAULT 15,

    maximum_length INTEGER NOT NULL DEFAULT 128,

    bcrypt_cost INTEGER NOT NULL DEFAULT 12,

    maximum_failed_attempts INTEGER NOT NULL DEFAULT 5,

    lock_duration_minutes INTEGER NOT NULL DEFAULT 15,

    password_history_limit INTEGER NOT NULL DEFAULT 5,

    password_expiration_days INTEGER,

    enforce_common_password_blocklist BOOLEAN
        NOT NULL DEFAULT TRUE,

    active BOOLEAN NOT NULL DEFAULT TRUE,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT valid_password_length CHECK (
        minimum_length >= 8
        AND maximum_length >= minimum_length
        AND maximum_length <= 256
    ),

    CONSTRAINT valid_bcrypt_cost CHECK (
        bcrypt_cost BETWEEN 10 AND 14
    ),

    CONSTRAINT valid_failed_attempts CHECK (
        maximum_failed_attempts BETWEEN 1 AND 20
    ),

    CONSTRAINT valid_lock_duration CHECK (
        lock_duration_minutes BETWEEN 1 AND 1440
    ),

    CONSTRAINT valid_history_limit CHECK (
        password_history_limit BETWEEN 0 AND 24
    ),

    CONSTRAINT valid_expiration CHECK (
        password_expiration_days IS NULL
        OR password_expiration_days BETWEEN 1 AND 365
    )
);

CREATE UNIQUE INDEX one_active_password_policy
ON password_policies (active)
WHERE active = TRUE;

INSERT INTO password_policies (
    policy_name,
    minimum_length,
    maximum_length,
    bcrypt_cost,
    maximum_failed_attempts,
    lock_duration_minutes,
    password_history_limit,
    password_expiration_days
)
VALUES (
    'Enterprise Default',
    15,
    128,
    12,
    5,
    15,
    5,
    NULL
);


-- ============================================================
-- 3. COMMON PASSWORD BLOCKLIST
-- ============================================================

CREATE TABLE common_passwords (
    password_value VARCHAR(256) PRIMARY KEY,
    added_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

INSERT INTO common_passwords (password_value)
VALUES
    ('password123456'),
    ('passwordpassword'),
    ('123456789012345'),
    ('qwerty123456789'),
    ('administrator123');


-- ============================================================
-- 4. USER ACCOUNTS
-- ============================================================

CREATE TABLE user_accounts (
    user_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    username VARCHAR(100) NOT NULL UNIQUE,

    email VARCHAR(254) NOT NULL UNIQUE,

    password_hash TEXT NOT NULL,

    policy_id BIGINT NOT NULL
        REFERENCES password_policies(policy_id),

    status account_status NOT NULL DEFAULT 'ACTIVE',

    failed_attempts INTEGER NOT NULL DEFAULT 0,

    locked_until TIMESTAMPTZ,

    password_changed_at TIMESTAMPTZ
        NOT NULL DEFAULT NOW(),

    password_expires_at TIMESTAMPTZ,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT valid_username CHECK (
        username ~ '^[A-Za-z0-9_.-]{3,100}$'
    ),

    CONSTRAINT valid_email CHECK (
        email ~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
    ),

    CONSTRAINT valid_failed_attempts CHECK (
        failed_attempts >= 0
    ),

    CONSTRAINT valid_locked_state CHECK (
        status = 'LOCKED'
        OR locked_until IS NULL
    ),

    CONSTRAINT nonempty_password_hash CHECK (
        length(password_hash) > 20
    )
);

CREATE INDEX idx_accounts_status
ON user_accounts(status);

CREATE INDEX idx_accounts_locked_until
ON user_accounts(locked_until)
WHERE status = 'LOCKED';

CREATE INDEX idx_accounts_password_expiration
ON user_accounts(password_expires_at)
WHERE password_expires_at IS NOT NULL;


-- ============================================================
-- 5. PASSWORD HISTORY
-- ============================================================

CREATE TABLE password_history (
    history_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    user_id BIGINT NOT NULL
        REFERENCES user_accounts(user_id)
        ON DELETE CASCADE,

    password_hash TEXT NOT NULL,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

    CONSTRAINT valid_history_hash CHECK (
        length(password_hash) > 20
    )
);

CREATE INDEX idx_password_history_user_date
ON password_history(user_id, created_at DESC);


-- ============================================================
-- 6. SECURITY AUDIT
-- ============================================================

CREATE TABLE security_audit (
    event_id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,

    user_id BIGINT
        REFERENCES user_accounts(user_id)
        ON DELETE SET NULL,

    username VARCHAR(100) NOT NULL,

    event_type security_event_type NOT NULL,

    event_details JSONB NOT NULL DEFAULT '{}'::JSONB,

    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX idx_security_audit_user_date
ON security_audit(user_id, created_at DESC);

CREATE INDEX idx_security_audit_event_date
ON security_audit(event_type, created_at DESC);


-- ============================================================
-- 7. PASSWORD POLICY VALIDATION
-- ============================================================

CREATE FUNCTION validate_password_policy(
    p_password TEXT,
    p_policy_id BIGINT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = password_security, pg_temp
AS $$
DECLARE
    v_policy password_policies%ROWTYPE;
BEGIN
    IF p_password IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT *
    INTO v_policy
    FROM password_policies
    WHERE policy_id = p_policy_id
      AND active = TRUE;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF char_length(p_password) < v_policy.minimum_length
       OR char_length(p_password) > v_policy.maximum_length THEN
        RETURN FALSE;
    END IF;

    IF btrim(p_password) = '' THEN
        RETURN FALSE;
    END IF;

    IF position(chr(0) IN p_password) > 0 THEN
        RETURN FALSE;
    END IF;

    IF v_policy.enforce_common_password_blocklist
       AND EXISTS (
           SELECT 1
           FROM common_passwords
           WHERE password_value = lower(p_password)
       ) THEN
        RETURN FALSE;
    END IF;

    RETURN TRUE;
END;
$$;


-- ============================================================
-- 8. PASSWORD HASHING
-- ============================================================

CREATE FUNCTION hash_password(
    p_password TEXT,
    p_policy_id BIGINT
)
RETURNS TEXT
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = password_security, public, pg_temp
AS $$
DECLARE
    v_cost INTEGER;
BEGIN
    IF NOT validate_password_policy(
        p_password,
        p_policy_id
    ) THEN
        RAISE EXCEPTION 'Password does not satisfy policy'
            USING ERRCODE = '22023';
    END IF;

    SELECT bcrypt_cost
    INTO v_cost
    FROM password_policies
    WHERE policy_id = p_policy_id
      AND active = TRUE;

    -- gen_salt creates a unique random bcrypt salt.
    -- crypt performs the adaptive password hashing.
    RETURN crypt(
        p_password,
        gen_salt('bf', v_cost)
    );
END;
$$;


-- ============================================================
-- 9. PASSWORD VERIFICATION
-- ============================================================

CREATE FUNCTION verify_password(
    p_password TEXT,
    p_stored_hash TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = public, pg_temp
AS $$
BEGIN
    IF p_password IS NULL OR p_stored_hash IS NULL THEN
        RETURN FALSE;
    END IF;

    IF p_stored_hash !~ '^\$2[aby]\$[0-9]{2}\$' THEN
        RETURN FALSE;
    END IF;

    RETURN crypt(
        p_password,
        p_stored_hash
    ) = p_stored_hash;

EXCEPTION
    WHEN OTHERS THEN
        RETURN FALSE;
END;
$$;


-- ============================================================
-- 10. SECURITY AUDIT INSERTION
-- ============================================================

CREATE FUNCTION record_security_event(
    p_user_id BIGINT,
    p_username VARCHAR(100),
    p_event security_event_type,
    p_details JSONB DEFAULT '{}'::JSONB
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = password_security, pg_temp
AS $$
BEGIN
    INSERT INTO security_audit (
        user_id,
        username,
        event_type,
        event_details
    )
    VALUES (
        p_user_id,
        p_username,
        p_event,
        COALESCE(p_details, '{}'::JSONB)
    );
END;
$$;


-- ============================================================
-- 11. ACCOUNT REGISTRATION
-- ============================================================

CREATE FUNCTION register_user(
    p_username VARCHAR(100),
    p_email VARCHAR(254),
    p_password TEXT
)
RETURNS BIGINT
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = password_security, pg_temp
AS $$
DECLARE
    v_policy_id BIGINT;
    v_hash TEXT;
    v_user_id BIGINT;
BEGIN
    SELECT policy_id
    INTO v_policy_id
    FROM password_policies
    WHERE active = TRUE
    FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No active password policy';
    END IF;

    v_hash := hash_password(
        p_password,
        v_policy_id
    );

    INSERT INTO user_accounts (
        username,
        email,
        password_hash,
        policy_id
    )
    VALUES (
        p_username,
        p_email,
        v_hash,
        v_policy_id
    )
    RETURNING user_id INTO v_user_id;

    PERFORM record_security_event(
        v_user_id,
        p_username,
        'ACCOUNT_CREATED',
        '{}'::JSONB
    );

    RETURN v_user_id;
END;
$$;


-- ============================================================
-- 12. ACCOUNT AUTHENTICATION
-- ============================================================

CREATE FUNCTION authenticate_user(
    p_username VARCHAR(100),
    p_password TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = password_security, pg_temp
AS $$
DECLARE
    v_account user_accounts%ROWTYPE;
    v_policy password_policies%ROWTYPE;
    v_valid BOOLEAN;
BEGIN
    SELECT *
    INTO v_account
    FROM user_accounts
    WHERE username = p_username
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF v_account.status = 'DISABLED' THEN
        RETURN FALSE;
    END IF;

    IF v_account.status = 'LOCKED' THEN

        IF v_account.locked_until > NOW() THEN
            RETURN FALSE;
        END IF;

        -- Automatic lockout expiry.
        UPDATE user_accounts
        SET status = 'ACTIVE',
            failed_attempts = 0,
            locked_until = NULL
        WHERE user_id = v_account.user_id;

        v_account.failed_attempts := 0;
        v_account.status := 'ACTIVE';
    END IF;

    SELECT *
    INTO v_policy
    FROM password_policies
    WHERE policy_id = v_account.policy_id;

    v_valid := verify_password(
        p_password,
        v_account.password_hash
    );

    IF v_valid THEN

        UPDATE user_accounts
        SET failed_attempts = 0,
            updated_at = NOW()
        WHERE user_id = v_account.user_id;

        PERFORM record_security_event(
            v_account.user_id,
            v_account.username,
            'AUTHENTICATION_SUCCESS',
            '{}'::JSONB
        );

        RETURN TRUE;
    END IF;

    UPDATE user_accounts
    SET failed_attempts = failed_attempts + 1,
        updated_at = NOW()
    WHERE user_id = v_account.user_id
    RETURNING * INTO v_account;

    IF (
        v_account.failed_attempts >=
        v_policy.maximum_failed_attempts
    ) THEN

        UPDATE user_accounts
        SET status = 'LOCKED',
            locked_until = NOW() +
                make_interval(
                    mins => v_policy.lock_duration_minutes
                )
        WHERE user_id = v_account.user_id;

        PERFORM record_security_event(
            v_account.user_id,
            v_account.username,
            'ACCOUNT_LOCKED',
            jsonb_build_object(
                'failed_attempts',
                v_account.failed_attempts
            )
        );
    END IF;

    PERFORM record_security_event(
        v_account.user_id,
        v_account.username,
        'AUTHENTICATION_FAILURE',
        jsonb_build_object(
            'failed_attempts',
            v_account.failed_attempts
        )
    );

    RETURN FALSE;
END;
$$;


-- ============================================================
-- 13. PASSWORD CHANGE
-- ============================================================

CREATE FUNCTION change_user_password(
    p_username VARCHAR(100),
    p_current_password TEXT,
    p_new_password TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY INVOKER
SET search_path = password_security, pg_temp
AS $$
DECLARE
    v_account user_accounts%ROWTYPE;
    v_policy password_policies%ROWTYPE;
    v_new_hash TEXT;
    v_history_limit INTEGER;
BEGIN
    SELECT *
    INTO v_account
    FROM user_accounts
    WHERE username = p_username
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN FALSE;
    END IF;

    IF v_account.status <> 'ACTIVE' THEN
        RETURN FALSE;
    END IF;

    IF NOT verify_password(
        p_current_password,
        v_account.password_hash
    ) THEN
        PERFORM record_security_event(
            v_account.user_id,
            v_account.username,
            'PASSWORD_REJECTED',
            '{}'::JSONB
        );

        RETURN FALSE;
    END IF;

    SELECT *
    INTO v_policy
    FROM password_policies
    WHERE policy_id = v_account.policy_id;

    IF NOT validate_password_policy(
        p_new_password,
        v_account.policy_id
    ) THEN
        RAISE EXCEPTION 'New password violates policy';
    END IF;

    IF verify_password(
        p_new_password,
        v_account.password_hash
    ) THEN
        RAISE EXCEPTION 'New password must differ from current password';
    END IF;

    v_history_limit := v_policy.password_history_limit;

    -- Compare the candidate against previous password verifiers.
    IF EXISTS (
        SELECT 1
        FROM password_history
        WHERE user_id = v_account.user_id
          AND verify_password(
              p_new_password,
              password_hash
          )
    ) THEN
        RAISE EXCEPTION 'Password was used previously';
    END IF;

    v_new_hash := hash_password(
        p_new_password,
        v_account.policy_id
    );

    INSERT INTO password_history (
        user_id,
        password_hash
    )
    VALUES (
        v_account.user_id,
        v_account.password_hash
    );

    UPDATE user_accounts
    SET password_hash = v_new_hash,
        password_changed_at = NOW(),
        password_expires_at = CASE
            WHEN v_policy.password_expiration_days IS NULL
            THEN NULL
            ELSE NOW() +
                make_interval(
                    days => v_policy.password_expiration_days
                )
        END,
        failed_attempts = 0,
        updated_at = NOW()
    WHERE user_id = v_account.user_id;

    -- Retain only the configured number of previous verifiers.
    DELETE FROM password_history
    WHERE user_id = v_account.user_id
      AND history_id NOT IN (
          SELECT history_id
          FROM password_history
          WHERE user_id = v_account.user_id
          ORDER BY created_at DESC, history_id DESC
          LIMIT v_history_limit
      );

    PERFORM record_security_event(
        v_account.user_id,
        v_account.username,
        'PASSWORD_CHANGED',
        '{}'::JSONB
    );

    RETURN TRUE;
END;
$$;


-- ============================================================
-- 14. PASSWORD EXPIRATION REPORTING
-- ============================================================

CREATE VIEW password_expiration_report AS
SELECT
    u.user_id,
    u.username,
    u.email,
    u.password_changed_at,
    u.password_expires_at,
    CASE
        WHEN u.password_expires_at IS NULL
            THEN 'NO EXPIRATION'
        WHEN u.password_expires_at <= NOW()
            THEN 'EXPIRED'
        WHEN u.password_expires_at <= NOW() + INTERVAL '7 days'
            THEN 'EXPIRING SOON'
        ELSE 'VALID'
    END AS expiration_status
FROM user_accounts u;


-- ============================================================
-- 15. ACCOUNT SECURITY REPORT
-- ============================================================

CREATE VIEW account_security_report AS
SELECT
    u.user_id,
    u.username,
    u.status,
    u.failed_attempts,
    u.locked_until,
    p.policy_name,
    p.bcrypt_cost,
    u.password_changed_at,
    u.created_at,
    COUNT(h.history_id) AS stored_password_history
FROM user_accounts u
JOIN password_policies p
    ON p.policy_id = u.policy_id
LEFT JOIN password_history h
    ON h.user_id = u.user_id
GROUP BY
    u.user_id,
    u.username,
    u.status,
    u.failed_attempts,
    u.locked_until,
    p.policy_name,
    p.bcrypt_cost,
    u.password_changed_at,
    u.created_at;


-- ============================================================
-- 16. SECURITY EVENT AGGREGATION
-- ============================================================

CREATE VIEW security_event_summary AS
SELECT
    event_type,
    COUNT(*) AS total_events,
    COUNT(DISTINCT user_id) AS affected_accounts,
    MAX(created_at) AS latest_event
FROM security_audit
GROUP BY event_type;


-- ============================================================
-- 17. DEMONSTRATION DATA
-- ============================================================

-- The sample passwords are deliberately fictional.
-- Password hashes are generated by bcrypt, never inserted
-- as plaintext into user_accounts.

DO $$
DECLARE
    v_alice BIGINT;
    v_bob BIGINT;
    v_carol BIGINT;
    v_password TEXT := 'Correct-Horse-Battery-47!';
BEGIN

    v_alice := register_user(
        'alice',
        'alice@example.com',
        v_password
    );

    v_bob := register_user(
        'bob',
        'bob@example.com',
        'Another-Strong-Password-83!'
    );

    v_carol := register_user(
        'carol',
        'carol@example.com',
        'Enterprise-Secure-Password-94!'
    );

    -- Successful authentication.
    IF NOT authenticate_user(
        'alice',
        v_password
    ) THEN
        RAISE EXCEPTION 'Alice authentication failed';
    END IF;

    -- Failed authentication.
    PERFORM authenticate_user(
        'bob',
        'Wrong-Password-12345!'
    );

    -- Invalid password policy.
    IF validate_password_policy(
        'short',
        (SELECT policy_id FROM password_policies
         WHERE active = TRUE)
    ) THEN
        RAISE EXCEPTION 'Invalid password accepted';
    END IF;

    -- Password change.
    IF NOT change_user_password(
        'carol',
        'Enterprise-Secure-Password-94!',
        'New-Enterprise-Password-95!'
    ) THEN
        RAISE EXCEPTION 'Password change failed';
    END IF;

END;
$$;


-- ============================================================
-- 18. RETRIEVAL AND VALIDATION QUERIES
-- ============================================================

-- Account retrieval.
SELECT
    user_id,
    username,
    status,
    failed_attempts,
    password_changed_at
FROM user_accounts
ORDER BY user_id;

-- Password policy validation.
SELECT
    username,
    validate_password_policy(
        'Example-Enterprise-Password-82!',
        policy_id
    ) AS policy_accepted
FROM user_accounts;

-- Password expiration evaluation.
SELECT *
FROM password_expiration_report
ORDER BY password_expires_at NULLS LAST;

-- Account lockout evaluation.
SELECT
    username,
    status,
    failed_attempts,
    locked_until,
    CASE
        WHEN status = 'LOCKED'
         AND locked_until > NOW()
        THEN 'LOCK ACTIVE'
        WHEN status = 'LOCKED'
        THEN 'LOCK EXPIRED'
        ELSE 'AVAILABLE'
    END AS availability
FROM user_accounts;

-- Security aggregation.
SELECT *
FROM security_event_summary
ORDER BY total_events DESC;

-- Audit retrieval.
SELECT
    username,
    event_type,
    event_details,
    created_at
FROM security_audit
ORDER BY created_at DESC;

-- Password history count.
SELECT
    u.username,
    COUNT(h.history_id) AS history_entries
FROM user_accounts u
LEFT JOIN password_history h
    ON h.user_id = u.user_id
GROUP BY u.user_id, u.username
ORDER BY u.username;

-- CTE: accounts requiring security review.
WITH account_risk AS (
    SELECT
        user_id,
        username,
        failed_attempts,
        status,
        CASE
            WHEN status = 'LOCKED' THEN 'HIGH'
            WHEN failed_attempts >= 3 THEN 'MEDIUM'
            ELSE 'LOW'
        END AS risk_level
    FROM user_accounts
)
SELECT *
FROM account_risk
WHERE risk_level IN ('HIGH', 'MEDIUM')
ORDER BY
    CASE risk_level
        WHEN 'HIGH' THEN 1
        ELSE 2
    END,
    failed_attempts DESC;


-- ============================================================
-- 19. TRANSACTIONAL PASSWORD CHANGE EXAMPLE
-- ============================================================

-- This transaction demonstrates atomic password rotation.
-- The sample user already changed their password above.
-- The transaction is rolled back to preserve demonstration state.

SAVEPOINT before_password_rotation;

SELECT change_user_password(
    'alice',
    'Correct-Horse-Battery-47!',
    'Rotated-Enterprise-Password-96!'
);

ROLLBACK TO SAVEPOINT before_password_rotation;


-- ============================================================
-- 20. DATABASE SECURITY
-- ============================================================

-- Application roles should receive only the required privileges.
-- Create roles separately according to deployment requirements.
--
-- Example:
--
-- CREATE ROLE password_app NOLOGIN;
--
-- GRANT USAGE ON SCHEMA password_security
-- TO password_app;
--
-- GRANT EXECUTE ON FUNCTION
-- password_security.register_user(VARCHAR, VARCHAR, TEXT)
-- TO password_app;
--
-- GRANT EXECUTE ON FUNCTION
-- password_security.authenticate_user(VARCHAR, TEXT)
-- TO password_app;
--
-- GRANT EXECUTE ON FUNCTION
-- password_security.change_user_password(VARCHAR, TEXT, TEXT)
-- TO password_app;
--
-- Do not grant direct SELECT access to password_hash.
-- Do not grant direct INSERT or UPDATE access to account
-- credential columns.
--
-- Application connections should use TLS.
-- Avoid logging password function arguments.
-- Restrict database administration and audit access.


-- ============================================================
-- 21. FINAL REPORT
-- ============================================================

SELECT
    COUNT(*) AS total_accounts,
    COUNT(*) FILTER (
        WHERE status = 'ACTIVE'
    ) AS active_accounts,
    COUNT(*) FILTER (
        WHERE status = 'LOCKED'
    ) AS locked_accounts,
    COUNT(*) FILTER (
        WHERE status = 'DISABLED'
    ) AS disabled_accounts
FROM user_accounts;

COMMIT;
